def test_order_history_totals_match_order_summary_including_discount(shop):
    # Gold customer: 2 x 6000 = 12000 subtotal, 15% discount -> 10200 total.
    discounted = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    plain = order(shop, "c2", ("PEN", 1)).body["order_id"]

    entries = shop.insights.handle_order_history("c2").body["orders"]

    by_id = {e["order_id"]: e for e in entries}
    assert by_id[discounted]["total_cents"] == 10_200
    assert by_id[plain]["total_cents"] == 300
    for order_id, entry in by_id.items():
        summary = shop.orders.handle_get(order_id).body
        assert entry == {"order_id": order_id, "status": summary["status"],
                         "total_cents": summary["total_cents"]}
    assert [e["order_id"] for e in entries] == [plain, discounted]

