class CustomerInsightsController:
    def __init__(self, orders: OrderService, customers: CustomerService) -> None:
        self._service = orders
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with totals as the order summary reports them."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        # list_for_customer returns creation order, so reverse it for newest first.
        entries: list[dict[str, Any]] = [
            {"order_id": o.order_id, "status": o.status,
             "total_cents": self._service.summarize(o).total_cents}
            for o in reversed(orders)
        ]
        return Response(200, {"customer_id": customer_id, "orders": entries})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Number of non-cancelled orders and their combined total, as the order history reports it."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        count, total = self._active_count_and_total(orders)
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": total})

